const (
	APICustomModelStatusStatusUnspecified APICustomModelStatus = "STATUS_UNSPECIFIED"
	APICustomModelStatusStatusImporting   APICustomModelStatus = "STATUS_IMPORTING"
	APICustomModelStatusStatusReady       APICustomModelStatus = "STATUS_READY"
	APICustomModelStatusStatusFailed      APICustomModelStatus = "STATUS_FAILED"
	APICustomModelStatusStatusDeleted     APICustomModelStatus = "STATUS_DELETED"
)

func NewAPICustomModelStatusFromString(s string) (APICustomModelStatus, error) {
	switch s {
	case "STATUS_UNSPECIFIED":
		return APICustomModelStatusStatusUnspecified, nil
	case "STATUS_IMPORTING":
		return APICustomModelStatusStatusImporting, nil
	case "STATUS_READY":
		return APICustomModelStatusStatusReady, nil
	case "STATUS_FAILED":
		return APICustomModelStatusStatusFailed, nil
	case "STATUS_DELETED":
		return APICustomModelStatusStatusDeleted, nil
	}
	var t APICustomModelStatus
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

