// Model Evaluation Run Statuses
type APIModelEvaluationRunStatus string

const (
	APIModelEvaluationRunStatusModelEvaluationRunStatusUnspecified   APIModelEvaluationRunStatus = "MODEL_EVALUATION_RUN_STATUS_UNSPECIFIED"
	APIModelEvaluationRunStatusModelEvaluationRunQueued              APIModelEvaluationRunStatus = "MODEL_EVALUATION_RUN_QUEUED"
	APIModelEvaluationRunStatusModelEvaluationRunRunningDataset      APIModelEvaluationRunStatus = "MODEL_EVALUATION_RUN_RUNNING_DATASET"
	APIModelEvaluationRunStatusModelEvaluationRunEvaluatingResults   APIModelEvaluationRunStatus = "MODEL_EVALUATION_RUN_EVALUATING_RESULTS"
	APIModelEvaluationRunStatusModelEvaluationRunCancelling          APIModelEvaluationRunStatus = "MODEL_EVALUATION_RUN_CANCELLING"
	APIModelEvaluationRunStatusModelEvaluationRunCancelled           APIModelEvaluationRunStatus = "MODEL_EVALUATION_RUN_CANCELLED"
	APIModelEvaluationRunStatusModelEvaluationRunSuccessful          APIModelEvaluationRunStatus = "MODEL_EVALUATION_RUN_SUCCESSFUL"
	APIModelEvaluationRunStatusModelEvaluationRunPartiallySuccessful APIModelEvaluationRunStatus = "MODEL_EVALUATION_RUN_PARTIALLY_SUCCESSFUL"
	APIModelEvaluationRunStatusModelEvaluationRunFailed              APIModelEvaluationRunStatus = "MODEL_EVALUATION_RUN_FAILED"
)

func NewAPIModelEvaluationRunStatusFromString(s string) (APIModelEvaluationRunStatus, error) {
	switch s {
	case "MODEL_EVALUATION_RUN_STATUS_UNSPECIFIED":
		return APIModelEvaluationRunStatusModelEvaluationRunStatusUnspecified, nil
	case "MODEL_EVALUATION_RUN_QUEUED":
		return APIModelEvaluationRunStatusModelEvaluationRunQueued, nil
	case "MODEL_EVALUATION_RUN_RUNNING_DATASET":
		return APIModelEvaluationRunStatusModelEvaluationRunRunningDataset, nil
	case "MODEL_EVALUATION_RUN_EVALUATING_RESULTS":
		return APIModelEvaluationRunStatusModelEvaluationRunEvaluatingResults, nil
	case "MODEL_EVALUATION_RUN_CANCELLING":
		return APIModelEvaluationRunStatusModelEvaluationRunCancelling, nil
	case "MODEL_EVALUATION_RUN_CANCELLED":
		return APIModelEvaluationRunStatusModelEvaluationRunCancelled, nil
	case "MODEL_EVALUATION_RUN_SUCCESSFUL":
		return APIModelEvaluationRunStatusModelEvaluationRunSuccessful, nil
	case "MODEL_EVALUATION_RUN_PARTIALLY_SUCCESSFUL":
		return APIModelEvaluationRunStatusModelEvaluationRunPartiallySuccessful, nil
	case "MODEL_EVALUATION_RUN_FAILED":
		return APIModelEvaluationRunStatusModelEvaluationRunFailed, nil
	}
	var t APIModelEvaluationRunStatus
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

