// - MODEL_USECASE_UNKNOWN: The use case of the model is unknown
//   - MODEL_USECASE_AGENT: The model maybe used in an agent
//   - MODEL_USECASE_FINETUNED: The model maybe used for fine tuning
//   - MODEL_USECASE_KNOWLEDGEBASE: The model maybe used for knowledge bases (embedding models)
//   - MODEL_USECASE_GUARDRAIL: The model maybe used for guardrails
//   - MODEL_USECASE_REASONING: The model usecase for reasoning
//   - MODEL_USECASE_SERVERLESS: The model usecase for serverless inference
//   - MODEL_USECASE_EVALUATION_JUDGE: The model usecase for evaluation judge
//   - MODEL_USECASE_CODING: The model usecase for coding-optimized models
//   - MODEL_USECASE_AUDIO: The model usecase for audio models
//   - MODEL_USECASE_RERANKING: The model usecase for knowledge base reranking (cross-encoder) models
//   - MODEL_USECASE_TEXT: The model usecase for text modality (non image, non audio, non embedding, non reranking) serverless chat models
type APIModelUsecase string

const (
	APIModelUsecaseModelUsecaseUnknown         APIModelUsecase = "MODEL_USECASE_UNKNOWN"
	APIModelUsecaseModelUsecaseAgent           APIModelUsecase = "MODEL_USECASE_AGENT"
	APIModelUsecaseModelUsecaseFinetuned       APIModelUsecase = "MODEL_USECASE_FINETUNED"
	APIModelUsecaseModelUsecaseKnowledgebase   APIModelUsecase = "MODEL_USECASE_KNOWLEDGEBASE"
	APIModelUsecaseModelUsecaseGuardrail       APIModelUsecase = "MODEL_USECASE_GUARDRAIL"
	APIModelUsecaseModelUsecaseReasoning       APIModelUsecase = "MODEL_USECASE_REASONING"
	APIModelUsecaseModelUsecaseServerless      APIModelUsecase = "MODEL_USECASE_SERVERLESS"
	APIModelUsecaseModelUsecaseEvaluationJudge APIModelUsecase = "MODEL_USECASE_EVALUATION_JUDGE"
	APIModelUsecaseModelUsecaseCoding          APIModelUsecase = "MODEL_USECASE_CODING"
	APIModelUsecaseModelUsecaseAudio           APIModelUsecase = "MODEL_USECASE_AUDIO"
	APIModelUsecaseModelUsecaseReranking       APIModelUsecase = "MODEL_USECASE_RERANKING"
	APIModelUsecaseModelUsecaseText            APIModelUsecase = "MODEL_USECASE_TEXT"
)

func NewAPIModelUsecaseFromString(s string) (APIModelUsecase, error) {
	switch s {
	case "MODEL_USECASE_UNKNOWN":
		return APIModelUsecaseModelUsecaseUnknown, nil
	case "MODEL_USECASE_AGENT":
		return APIModelUsecaseModelUsecaseAgent, nil
	case "MODEL_USECASE_FINETUNED":
		return APIModelUsecaseModelUsecaseFinetuned, nil
	case "MODEL_USECASE_KNOWLEDGEBASE":
		return APIModelUsecaseModelUsecaseKnowledgebase, nil
	case "MODEL_USECASE_GUARDRAIL":
		return APIModelUsecaseModelUsecaseGuardrail, nil
	case "MODEL_USECASE_REASONING":
		return APIModelUsecaseModelUsecaseReasoning, nil
	case "MODEL_USECASE_SERVERLESS":
		return APIModelUsecaseModelUsecaseServerless, nil
	case "MODEL_USECASE_EVALUATION_JUDGE":
		return APIModelUsecaseModelUsecaseEvaluationJudge, nil
	case "MODEL_USECASE_CODING":
		return APIModelUsecaseModelUsecaseCoding, nil
	case "MODEL_USECASE_AUDIO":
		return APIModelUsecaseModelUsecaseAudio, nil
	case "MODEL_USECASE_RERANKING":
		return APIModelUsecaseModelUsecaseReranking, nil
	case "MODEL_USECASE_TEXT":
		return APIModelUsecaseModelUsecaseText, nil
	}
	var t APIModelUsecase
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

