// - RETRIEVAL_METHOD_UNKNOWN: The retrieval method is unknown
//   - RETRIEVAL_METHOD_REWRITE: The retrieval method is rewrite
//   - RETRIEVAL_METHOD_STEP_BACK: The retrieval method is step back
//   - RETRIEVAL_METHOD_SUB_QUERIES: The retrieval method is sub queries
//   - RETRIEVAL_METHOD_NONE: The retrieval method is none
type APIRetrievalMethod string

const (
	APIRetrievalMethodRetrievalMethodUnknown    APIRetrievalMethod = "RETRIEVAL_METHOD_UNKNOWN"
	APIRetrievalMethodRetrievalMethodRewrite    APIRetrievalMethod = "RETRIEVAL_METHOD_REWRITE"
	APIRetrievalMethodRetrievalMethodStepBack   APIRetrievalMethod = "RETRIEVAL_METHOD_STEP_BACK"
	APIRetrievalMethodRetrievalMethodSubQueries APIRetrievalMethod = "RETRIEVAL_METHOD_SUB_QUERIES"
	APIRetrievalMethodRetrievalMethodNone       APIRetrievalMethod = "RETRIEVAL_METHOD_NONE"
)

func NewAPIRetrievalMethodFromString(s string) (APIRetrievalMethod, error) {
	switch s {
	case "RETRIEVAL_METHOD_UNKNOWN":
		return APIRetrievalMethodRetrievalMethodUnknown, nil
	case "RETRIEVAL_METHOD_REWRITE":
		return APIRetrievalMethodRetrievalMethodRewrite, nil
	case "RETRIEVAL_METHOD_STEP_BACK":
		return APIRetrievalMethodRetrievalMethodStepBack, nil
	case "RETRIEVAL_METHOD_SUB_QUERIES":
		return APIRetrievalMethodRetrievalMethodSubQueries, nil
	case "RETRIEVAL_METHOD_NONE":
		return APIRetrievalMethodRetrievalMethodNone, nil
	}
	var t APIRetrievalMethod
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

