// Types of spans in a trace
type APITraceSpanType string

const (
	APITraceSpanTypeTraceSpanTypeUnknown   APITraceSpanType = "TRACE_SPAN_TYPE_UNKNOWN"
	APITraceSpanTypeTraceSpanTypeLlm       APITraceSpanType = "TRACE_SPAN_TYPE_LLM"
	APITraceSpanTypeTraceSpanTypeRetriever APITraceSpanType = "TRACE_SPAN_TYPE_RETRIEVER"
	APITraceSpanTypeTraceSpanTypeTool      APITraceSpanType = "TRACE_SPAN_TYPE_TOOL"
	APITraceSpanTypeTraceSpanTypeAgent     APITraceSpanType = "TRACE_SPAN_TYPE_AGENT"
	APITraceSpanTypeTraceSpanTypeWorkflow  APITraceSpanType = "TRACE_SPAN_TYPE_WORKFLOW"
)

func NewAPITraceSpanTypeFromString(s string) (APITraceSpanType, error) {
	switch s {
	case "TRACE_SPAN_TYPE_UNKNOWN":
		return APITraceSpanTypeTraceSpanTypeUnknown, nil
	case "TRACE_SPAN_TYPE_LLM":
		return APITraceSpanTypeTraceSpanTypeLlm, nil
	case "TRACE_SPAN_TYPE_RETRIEVER":
		return APITraceSpanTypeTraceSpanTypeRetriever, nil
	case "TRACE_SPAN_TYPE_TOOL":
		return APITraceSpanTypeTraceSpanTypeTool, nil
	case "TRACE_SPAN_TYPE_AGENT":
		return APITraceSpanTypeTraceSpanTypeAgent, nil
	case "TRACE_SPAN_TYPE_WORKFLOW":
		return APITraceSpanTypeTraceSpanTypeWorkflow, nil
	}
	var t APITraceSpanType
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

func (a APITraceSpanType) Ptr() *APITraceSpanType {
	return &a
}

